<script setup>
import { listTypes,normalizeList } from '../textLists.js';
import { themeColors } from '../themes.js';
const props=defineProps({value:Object,theme:Object,scale:Number});const emit=defineEmits(['change']);
function change(key,value){emit('change','list',normalizeList({...props.value,[key]:value}),{[key]:value});}
</script>
<template><label>Type de liste<select :value="value.type" aria-label="Type de liste" @change="change('type',$event.target.value)"><option v-for="[id,name] in listTypes" :key="id" :value="id">{{name}}</option></select></label><template v-if="value.type!=='none'"><p class="field-help">Un élément par ligne. Les retours automatiques restent alignés avec le texte.</p><label v-if="value.type==='custom'">Symbole<input :value="value.symbol" maxlength="8" aria-label="Symbole de la liste" @input="change('symbol',$event.target.value)"></label><label v-if="['decimal','alpha','roman'].includes(value.type)">Commencer à<input type="number" min="1" max="999" :value="value.start" aria-label="Début de numérotation" @input="change('start',$event.target.value)"></label><label v-for="[key,name,max] in [['indent','Retrait',240],['gap','Écart symbole / texte',80],['spacing','Espace entre les éléments',120]]" :key="key">{{name}} · px<input type="number" min="0" :max="max*scale" :value="Math.round(value[key]*scale)" :aria-label="name+' de la liste'" @input="change(key,Number($event.target.value)/scale)"></label><label>Couleur des marqueurs<select :value="value.colorRole||''" aria-label="Couleur des marqueurs" @change="emit('change','list',normalizeList({...value,colorRole:$event.target.value||null,color:null}),{colorRole:$event.target.value||null,color:null})"><option value="">Comme le texte</option><option v-for="c in themeColors(theme)" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Couleur personnalisée<input type="color" :value="value.color||theme.ink" aria-label="Couleur personnalisée des marqueurs" @input="emit('change','list',normalizeList({...value,colorRole:null,color:$event.target.value}),{colorRole:null,color:$event.target.value})"></label></template></template>
